import {
  Object3D,
  Mesh,
  PlaneGeometry,
  Vector3,
  Color,
  LinearFilter,
  RepeatWrapping,
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {{position:[number,number,number], rotation:[number,number,number], scale:[number,number,number]}} scenePlacement
 * @property {any[]} cinematicPrimitives
 * @property {any[]} textContent
 *
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {{[key:string]:(target:any,params:any)=>void}} primitives
 * @property {any} fontAtlas
 * @property {(event:string)=>void} [emit]
 */

/**
 * Create a journal card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  // --- Geometry --------------------------------------------------------------
  const imgUrl = config.assets?.imageUrl;
  const tex = ctx.textureLoader(imgUrl);
  tex.minFilter = LinearFilter;
  tex.wrapS = tex.wrapT = RepeatWrapping;

  // Aspect based on atlas source rect (512x320) if not provided fall back to texture size
  const aspect = 512 / 320; // width / height

  const planeGeom = new PlaneGeometry(aspect, 1);
  const planeMat = new MeshBasicNodeMaterial({ map: tex });
  const planeMesh = new Mesh(planeGeom, planeMat);
  planeMesh.castShadow = false;
  planeMesh.receiveShadow = false;

  // --- Placement -------------------------------------------------------------
  const [px, py, pz] = config.scenePlacement?.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.scenePlacement?.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.scenePlacement?.scale ?? [1, 1, 1];

  planeMesh.position.set(px, py, pz);
  planeMesh.rotation.set(rx, ry, rz);
  planeMesh.scale.set(sx, sy, sz);

  // --- Stock Badge -----------------------------------------------------------
  const badgeGeom = new PlaneGeometry(0.4, 0.2);
  const badgeMat = new MeshBasicNodeMaterial({ color: 0x00ff00, transparent: true, opacity: 0.85 });
  const badgeMesh = new Mesh(badgeGeom, badgeMat);
  // Position badge at top‑right corner of the card
  badgeMesh.position.set(
    aspect / 2 - 0.2,
    0.5 - 0.1,
    0.01
  );
  badgeMesh.visible = false;

  // --- Container -------------------------------------------------------------
  const group = new Object3D();
  group.add(planeMesh);
  group.add(badgeMesh);

  // --- Interaction Handlers --------------------------------------------------
  const baseY = py;
  const hoverDelta = 0.15; // subtle lift
  const hoverDuration = 0.7;
  const clickScale = 0.97;
  const clickDuration = 0.12;

  const handlers = {};

  handlers.hoverEnter = () => {
    gsap.to(planeMesh.position, {
      y: baseY + hoverDelta,
      duration: hoverDuration,
      ease: 'power3.out',
    });
  };

  handlers.hoverLeave = () => {
    gsap.to(planeMesh.position, {
      y: baseY,
      duration: hoverDuration,
      ease: 'power3.out',
    });
  };

  handlers.click = () => {
    // press‑down animation
    gsap.to(planeMesh.scale, {
      x: clickScale,
      y: clickScale,
      z: clickScale,
      duration: clickDuration,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(planeMesh.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: clickDuration,
          ease: 'back.out',
        });
      },
    });
    // emit navigation event if context provides an emitter
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  };

  // expose handlers via userData
  group.userData.handlers = {
    hoverEnter: handlers.hoverEnter,
    hoverLeave: handlers.hoverLeave,
    click: handlers.click,
  };

  // --- Stock Update Helper ---------------------------------------------------
  group.userData.updateStock = (inStock) => {
    badgeMesh.visible = true;
    const col = inStock ? 0x00ff00 : 0xff2a38; // green for in‑stock, accent red otherwise
    badgeMat.color = new Color(col);
  };

  // --- Apply Cinematic Primitives (if any) -----------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(group, prim.params);
      }
    }
  }

  // --- Cleanup ---------------------------------------------------------------
  group.userData.cleanup = () => {
    gsap.killTweensOf(planeMesh.position);
    gsap.killTweensOf(planeMesh.scale);
    planeGeom.dispose();
    badgeGeom.dispose();
    planeMat.dispose();
    badgeMat.dispose();
    // If texture is not shared elsewhere, dispose it.
    if (tex && tex.isTexture && !tex.userData?.shared) {
      tex.dispose();
    }
  };

  return group;
}
